-- ============================================================================
-- SWIGGY DATABASE ONE-CLICK DATA POPULATION SCRIPT
-- Run this script directly in MySQL Workbench by clicking the Lightning Bolt ⚡
-- ============================================================================

USE swiggy_db;

SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
SET AUTOCOMMIT = 0;

TRUNCATE TABLE order_items;
TRUNCATE TABLE orders;
TRUNCATE TABLE menu_items;
TRUNCATE TABLE delivery_partners;
TRUNCATE TABLE restaurants;
TRUNCATE TABLE users;







































































































COMMIT;
SET FOREIGN_KEY_CHECKS = 1;

-- Verification Check
SELECT 'users' AS table_name, COUNT(*) AS rows_loaded FROM users
UNION ALL SELECT 'restaurants', COUNT(*) FROM restaurants
UNION ALL SELECT 'menu_items', COUNT(*) FROM menu_items
UNION ALL SELECT 'delivery_partners', COUNT(*) FROM delivery_partners
UNION ALL SELECT 'orders', COUNT(*) FROM orders
UNION ALL SELECT 'order_items', COUNT(*) FROM order_items;
